import json
import subprocess

def get_etcd_data(ip, path, ssl=False):
    url = f'https://{ip}/{path}'
    if ssl:
        cert_path = '/etc/kubernetes/pki/apiserver.crt'
        key_path = '/etc/kubernetes/pki/apiserver.key'
        curl_command = f'curl -k --cert {cert_path} --key {key_path} {url}'
    else:
        curl_command = f'curl {url}'

    try:
        response = subprocess.check_output(curl_command, shell=True, text=True)
        return json.loads(response)
    except subprocess.CalledProcessError as e:
        return {'error': str(e)}

